#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""xref 回包函数 0xca78 / bt_att_send(0x7bc8) 全部调用点, 检查 x4(data)/w5(len) 来源
另: 0x04/0x05 完成路径 (0xeee0/0xef20) 是否回显重组内容"""
import sys
sys.stdout.reconfigure(encoding='utf-8', errors='replace')
from elftools.elf.elffile import ELFFile
from capstone import *

elf = ELFFile(open("btgatt-server.go2.elf", 'rb'))
md = Cs(CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN); md.detail = True
texts = [(s['sh_addr'], s.data()) for s in elf.iter_sections()
         if s['sh_flags'] & 0x4 and s['sh_type'] == 'SHT_PROGBITS']

for target, label in ((0xca78, 'send_response(0xca78)'), (0x7bc8, 'bt_att_send')):
    print(f"=== xref {label} ===")
    for base, data in texts:
        insns = list(md.disasm(data, base))
        for i, ins in enumerate(insns):
            if ins.mnemonic == 'bl' and ins.operands and ins.operands[0].imm == target:
                ctx = insns[max(0,i-8):i+1]
                print(f"--- 0x{ins.address:x} ---")
                for c in ctx:
                    print(f"    {c.address:6x}: {c.mnemonic:8s} {c.op_str}")

print("\n=== 0x04 完成路径 0xeee0 / 0x05 完成 0xef20 ===")
for base, data in texts:
    if base <= 0xeee0 < base+len(data):
        off = 0xeee0 - base
        for ins in md.disasm(data[off:off+0x120], 0xeee0):
            print(f"  {ins.address:6x}: {ins.mnemonic:8s} {ins.op_str}")
        break

