import sys
sys.stdout.reconfigure(encoding='utf-8', errors='replace')
from elftools.elf.elffile import ELFFile
from capstone import *
from capstone.arm64 import *
ELF = r"C:\zyh\work\漏洞整理\unitree_GO2\GO2蓝牙btgatt-server分片重组溢出到RCE\scripts\btgatt-server.go2.elf"
elf = ELFFile(open(ELF,'rb'))
md = Cs(CS_ARCH_ARM64, CS_MODE_LITTLE_ENDIAN); md.detail = True
sec = elf.get_section_by_name('.text')
base, data = sec['sh_addr'], sec.data()
insns = list(md.disasm(data, base))

# symbol table for naming
symtab = elf.get_section_by_name('.symtab')
sym_by_addr = {}
for sym in symtab.iter_symbols():
    if sym['st_info']['type']=='STT_FUNC' and sym['st_value']:
        sym_by_addr.setdefault(sym['st_value'], sym.name)
def name_of(a):
    # find nearest preceding symbol
    best=None;bd=None
    for v,n in sym_by_addr.items():
        if v<=a and (bd is None or a-v<bd): bd=a-v;best=n
    return f"{best}+0x{bd:x}" if bd else f"0x{a:x}"

OBJ = {}
for sym in symtab.iter_symbols():
    if sym['st_info']['type']=='STT_OBJECT' and 0x2e1e0 <= sym['st_value'] < 0x2eb20:
        OBJ[sym['st_value']] = (sym.name, sym['st_size'])
def obj_name(a):
    # find containing object
    best=None
    for v,(n,sz) in OBJ.items():
        if v <= a < v+max(sz,1):
            return f"{n}+0x{a-v:x}"
    # nearest below
    c=[(v,n) for v,(n,sz) in OBJ.items() if v<=a]
    if c:
        v,n=max(c); return f"{n}+0x{a-v:x}(oob?)"
    return f"0x{a:x}"

# pass: track adrp -> register page, then add/ldr/str with reg
import collections
refs = collections.defaultdict(list)  # global_addr -> list of (insn_idx, kind)
N=len(insns)
for i,ins in enumerate(insns):
    if ins.mnemonic=='adrp':
        rd=ins.reg_name(ins.operands[0].reg); page=ins.operands[1].imm
        # scan forward until reg clobbered (max 6 insns)
        for j in range(i+1, min(i+8,N)):
            ins2=insns[j]
            if ins2.mnemonic in ('add',) and len(ins2.operands)==3 and ins2.reg_name(ins2.operands[1].reg)==rd and ins2.operands[2].type==ARM64_OP_IMM:
                tgt=page+ins2.operands[2].imm
                if 0x2e1e0<=tgt<0x2eb40:
                    refs[tgt].append((j,'addr-taken', ins2.reg_name(ins2.operands[0].reg)))
            if ins2.mnemonic in ('ldr','str','ldrb','strb','ldrh','strh','ldrsw','ldur','stur','ldurb','sturb') and len(ins2.operands)>=2:
                mem=ins2.operands[-1]
                if mem.type==ARM64_OP_MEM and ins2.reg_name(mem.mem.base)==rd:
                    tgt=page+mem.mem.disp
                    if 0x2e1e0<=tgt<0x2eb40:
                        kind='WRITE' if ins2.mnemonic.startswith('str') else 'READ'
                        refs[tgt].append((j, f'{kind}({ins2.mnemonic} {ins2.reg_name(ins2.operands[0].reg)})', None))
            # clobber check: writes to rd
            if ins2.operands and ins2.operands[0].type==ARM64_OP_REG and ins2.reg_name(ins2.operands[0].reg)==rd and ins2.mnemonic!='adrp':
                if ins2.mnemonic in ('mov','movk','orr','adrp','bl','ldr') : break
                if ins2.mnemonic in ('add','ldr','str','ldrb','strb'): continue
                break
            if ins2.mnemonic=='bl': break

for tgt in sorted(refs):
    print(f"\n### {obj_name(tgt)}  @0x{tgt:x}")
    for j,kind,dst in refs[tgt]:
        ins=insns[j]
        # function context: find nearest func symbol
        fn = name_of(ins.address)
        print(f"  0x{ins.address:06x} [{fn:40s}] {kind:24s} {ins.mnemonic} {ins.op_str}")
